// Roll loot for every selected monster token, using your character's loot bonus
const looter = game.user.character ?? null;
for (const token of canvas.tokens.controlled) {
  if (token.actor?.type === "monster") await token.actor.rollLoot({ looter });
}

const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (actor) game.sw25.SpellbookApp.openFor(actor);
else ui.notifications.warn("Select a token first.");

// Prompt for a check and roll it for the selected token (or your character)
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("Select a token first.");
const options = Object.keys(CONFIG.SW25.checks).map(k => `<option value="${k}">${game.i18n.localize(`SW25.Check.${k}`)}</option>`).join("");
const key = await foundry.applications.api.DialogV2.prompt({
  window: { title: "Check" },
  content: `<select name="check" style="width:100%">${options}</select>`,
  ok: { callback: (ev, b) => b.form.elements.check.value }
});
if (key) actor.rollCheck(key);

const value = await foundry.applications.api.DialogV2.prompt({
  window: { title: "Award experience" },
  content: `<input type="number" name="exp" value="1000" style="width:100%">`,
  ok: { callback: (ev, b) => Number(b.form.elements.exp.value) || 0 }
});
if (!value) return;
const actors = canvas.tokens.controlled.map(t => t.actor).filter(a => a?.type === "character");
for (const a of actors) await a.update({ "system.exp.value": a.system.exp.value + value, "system.exp.total": a.system.exp.total + value });
ui.notifications.info(`${value} EXP → ${actors.map(a => a.name).join(", ")}`);

// Ask for a power and critical value and roll on the power table
const data = await foundry.applications.api.DialogV2.prompt({
  window: { title: "Power table" },
  content: `<div class="form-group"><label>Power</label><input type="number" name="power" value="20"></div><div class="form-group"><label>Critical value</label><input type="number" name="crit" value="10"></div><div class="form-group"><label>Extra damage</label><input type="number" name="extra" value="0"></div>`,
  ok: { callback: (ev, b) => ({ power: Number(b.form.elements.power.value), critical: Number(b.form.elements.crit.value), extra: Number(b.form.elements.extra.value) }) }
});
if (!data) return;
const { result, rolls } = await game.sw25.rollPower(data);
const steps = result.steps.map(s => `${s.dice.join("+")} → ${s.value}${s.crit ? " (crit)" : ""}`).join("<br>");
ChatMessage.create({ rolls, content: `<div class="sw25"><strong>Power ${data.power}</strong><br>${steps}<br>= <strong>${result.calculated}</strong></div>` });

const current = game.settings.get("swordworld25", "monsterFixedValues");
await game.settings.set("swordworld25", "monsterFixedValues", !current);
ui.notifications.info(`Monster fixed values: ${!current ? "ON" : "OFF"}`);
